REVOKE EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) FROM anon; REVOKE EXECUTE ON FUNCTION public.ensure_profile() FROM anon; CREATE OR REPLACE FUNCTION public.ensure_profile() RETURNS public.profiles LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE p public.profiles; uid uuid:=auth.uid(); metadata jsonb:=auth.jwt()->'user_metadata'; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO p FROM public.profiles WHERE id=uid; IF p.id IS NULL THEN INSERT INTO public.profiles(id,name,username) VALUES(uid,coalesce(nullif(metadata->>'name',''),'مستخدمة'),coalesce(nullif(metadata->>'username',''),'user_'||replace(uid::text,'-',''))) RETURNING * INTO p; END IF; RETURN p; END $$; CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;